<?php require __DIR__.'/config.php';header('Content-Type: application/json; charset=utf-8');$action=$_GET['action']??'';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'POST required']);exit;}function respond(bool $ok,string $message,int $code=200):never{http_response_code($code);echo json_encode(['ok'=>$ok,'message'=>$message]);exit;}if($action==='submit_application'){$learner=trim($_POST['learner_name']??'');$grade=trim($_POST['grade']??'');$guardian=trim($_POST['guardian_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$curriculum=trim($_POST['curriculum']??'');$message=trim($_POST['message']??'');if(!$learner||!$guardian||!filter_var($email,FILTER_VALIDATE_EMAIL))respond(false,'Please complete the required fields.',422);$items=read_json('applications');$items[]=['id'=>next_id($items),'learner_name'=>$learner,'grade'=>$grade,'guardian_name'=>$guardian,'email'=>$email,'phone'=>$phone,'curriculum'=>$curriculum,'message'=>$message,'status'=>'New','created_at'=>date('c')];write_json('applications',$items);respond(true,'Application enquiry received. The administration can now review it in the CMS.');}if($action==='submit_enquiry'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$message)respond(false,'Please complete your name, email and message.',422);$items=read_json('enquiries');$items[]=['id'=>next_id($items),'name'=>$name,'email'=>$email,'phone'=>$phone,'subject'=>$subject,'message'=>$message,'status'=>'New','created_at'=>date('c')];write_json('enquiries',$items);respond(true,'Your enquiry has been received.');}respond(false,'Unknown action.',404);
